// ============================================================
// PhotonBoard — MVR (DIN SPEC 15801) export
//
// One layer with every patched fixture: stable UUID (from the patch
// id; fixtures imported from an MVR keep their original UUID),
// name, FixtureID / FixtureIDNumeric (fid), GDTFSpec + GDTFMode,
// Addresses (absolute DMX address), DMXInvertPan / Tilt, a colour
// (the fixture's first group) and a Matrix built from the 3D
// position and the static aim (mounting location / tilt / direction).
// Every fixture type used is embedded as a GDTF generated by
// ../gdtf/gdtf-export.ts. Pure apart from node's crypto.
// ============================================================

import AdmZip from 'adm-zip'
import type { ImportWarning } from '../../../shared/interchange'
import { DEFAULT_ROOM_CONFIG, type FixtureDefinition, type ShowFile } from '../../../shared/types'
import { APP_NAME, APP_VERSION } from '../gdtf/app-info'
import { hexToCieText } from '../gdtf/color'
import { writeGdtf } from '../gdtf/gdtf-export'
import { stableUuid } from '../gdtf/uuid'
import { el, serializeXml, type XEl } from '../gdtf/xml'
import { aimDirection, autoPosition, beamFromRotation3D, formatMvrMatrix, pbToMvr, rotationForBeam } from './geometry'

export interface MvrExportOptions {
  now?: Date
}

const PATCH_UUID_RE = /^mvr-([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i

export function writeMvr(show: ShowFile, fixtures: FixtureDefinition[], opts: MvrExportOptions = {}): { bytes: Uint8Array; xml: string; warnings: ImportWarning[] } {
  const warnings: ImportWarning[] = []
  const defs = new Map(fixtures.map((f) => [f.id, f]))
  const room = show.roomConfig ?? DEFAULT_ROOM_CONFIG

  // ---- one GDTF per fixture type used ----
  const gdtfFiles = new Map<string, { fileName: string; bytes: Uint8Array; modeNames: Map<string, string> }>()
  const takenFiles = new Set<string>()
  for (const id of new Set(show.patch.map((p) => p.fixtureDefId))) {
    const def = defs.get(id)
    if (!def) continue
    const res = writeGdtf(def, { now: opts.now, appVersion: APP_VERSION })
    let fileName = res.fileName
    for (let i = 2; takenFiles.has(fileName.toLowerCase()); i++) fileName = res.fileName.replace(/\.gdtf$/i, `_${i}.gdtf`)
    takenFiles.add(fileName.toLowerCase())
    gdtfFiles.set(id, { fileName, bytes: res.bytes, modeNames: res.modeNames })
    for (const w of res.warnings) warnings.push({ ...w, params: { ...(w.params ?? {}), fixture: def.name } })
    if (def.source === 'gdtf') {
      warnings.push({ level: 'info', code: 'mvr.export.gdtfRegenerated', params: { fixture: def.name }, message: `"${def.name}" came from a GDTF file; the embedded GDTF is regenerated from PhotonBoard's definition (3D models and gobo images are not included)` })
    }
  }

  // ---- fixtures ----
  const groupColor = new Map<string, string>()
  for (const g of show.groups) for (const id of g.fixtureIds) if (!groupColor.has(id) && g.color) groupColor.set(id, g.color)
  const fixturesXml: XEl[] = []
  const usedUuids = new Set<string>()
  let missingDefs = 0
  // FixtureID is mandatory in MVR: fixtures without a number get the lowest free ones
  const takenFids = new Set(show.patch.map((p) => p.fid).filter((n): n is number => typeof n === 'number' && n > 0))
  let nextFid = 1
  const freeFid = () => { while (takenFids.has(nextFid)) nextFid++; takenFids.add(nextFid); return nextFid }
  show.patch.forEach((entry, index) => {
    const def = defs.get(entry.fixtureDefId)
    const gdtf = gdtfFiles.get(entry.fixtureDefId)
    if (!def) missingDefs++
    const fromMvr = PATCH_UUID_RE.exec(entry.id)?.[1]?.toUpperCase()
    let uuid = fromMvr ?? stableUuid('photonboard-patch', entry.id)
    if (usedUuids.has(uuid)) uuid = stableUuid('photonboard-patch-dup', `${entry.id}#${index}`)
    usedUuids.add(uuid)

    const pos = entry.position3D ?? autoPosition(index, show.patch.length, room, entry.mountingLocation)
    const beamPb = entry.rotation3D ? beamFromRotation3D(entry.rotation3D) : aimDirection(entry)
    const r = rotationForBeam(pbToMvr(beamPb))
    const o = pbToMvr({ x: pos.x * 1000, y: pos.y * 1000, z: pos.z * 1000 })
    const absolute = Math.max(0, entry.universe) * 512 + Math.max(1, Math.min(512, entry.address))
    const fid = entry.fid && entry.fid > 0 ? entry.fid : freeFid()
    const color = groupColor.get(entry.id)
    const modeName = gdtf?.modeNames.get(entry.modeName) ?? (def ? gdtf?.modeNames.get(def.modes[0]?.name ?? '') : undefined)

    fixturesXml.push(el('Fixture', { name: entry.name || def?.name || `Fixture ${fid}`, uuid }, [
      el('Matrix', {}, formatMvrMatrix({ r, o })),
      gdtf ? el('GDTFSpec', {}, gdtf.fileName) : null,
      gdtf && modeName ? el('GDTFMode', {}, modeName) : null,
      el('CastShadow', {}, 'false'),
      entry.panInvert ? el('DMXInvertPan', {}, 'true') : null,
      entry.tiltInvert ? el('DMXInvertTilt', {}, 'true') : null,
      el('Addresses', {}, [el('Address', { break: 0 }, String(absolute))]),
      el('FixtureID', {}, String(fid)),
      el('FixtureIDNumeric', {}, String(fid)),
      el('UnitNumber', {}, '0'),
      el('CustomIdType', {}, '0'),
      el('CustomId', {}, '0'),
      color ? el('Color', {}, hexToCieText(color)) : null
    ]))
  })
  if (missingDefs > 0) {
    warnings.push({ level: 'warning', code: 'mvr.export.missingDefinition', params: { count: missingDefs }, message: `${missingDefs} fixture(s) have no fixture definition; they are exported without a GDTF` })
  }

  const layerUuid = stableUuid('photonboard-layer', show.name || 'show')
  const doc = el('GeneralSceneDescription', { verMajor: 1, verMinor: 6, provider: APP_NAME, providerVersion: APP_VERSION }, [
    el('UserData', {}, [el('Data', { provider: APP_NAME, ver: APP_VERSION })]),
    el('Scene', {}, [
      el('AUXData'),
      el('Layers', {}, [
        el('Layer', { name: show.name || 'PhotonBoard', uuid: layerUuid }, [
          el('ChildList', {}, fixturesXml)
        ])
      ])
    ])
  ])
  const xml = serializeXml(doc)

  // What MVR does not carry
  const notCarried: string[] = []
  if (show.groups.length) notCarried.push(`${show.groups.length} group(s)`)
  if (show.presets.length) notCarried.push(`${show.presets.length} preset(s)`)
  if (show.cuelists.length) notCarried.push(`${show.cuelists.length} cue list(s)`)
  if (show.chases.length) notCarried.push(`${show.chases.length} chase(s)`)
  if (show.effects.length) notCarried.push(`${show.effects.length} effect(s)`)
  if ((show.macros ?? []).length) notCarried.push(`${show.macros!.length} macro(s)`)
  if (notCarried.length) {
    const count = show.groups.length + show.presets.length + show.cuelists.length + show.chases.length + show.effects.length + (show.macros ?? []).length
    warnings.push({ level: 'info', code: 'mvr.export.rigOnly', params: { count }, message: `MVR describes the rig (fixtures, patch, positions) only; not exported: ${notCarried.join(', ')}` })
  }
  if (room.trussBars.length) {
    warnings.push({ level: 'info', code: 'mvr.export.trusses', params: { count: room.trussBars.length }, message: `${room.trussBars.length} truss bar(s) are not exported (MVR trusses need 3D models)` })
  }

  const zip = new AdmZip()
  zip.addFile('GeneralSceneDescription.xml', Buffer.from(xml, 'utf-8'))
  for (const g of gdtfFiles.values()) zip.addFile(g.fileName, Buffer.from(g.bytes))
  return { bytes: new Uint8Array(zip.toBuffer()), xml, warnings }
}
